#!/usr/bin/env python3
"""Regenerate the top-level README summary table from manifest.json.

Reads manifest.json, finds the best result per (suite, subset), rewrites the
"Latest headline results" table in README.md between the auto-generated markers.
"""

import json
import re
from collections import defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
MANIFEST = ROOT / "manifest.json"
README = ROOT / "README.md"

BEGIN_MARK = "<!-- generated by scripts/generate-readme.py -->"
END_MARK = "<!-- /generated -->"


def best_per_group(runs):
    """Group by (suite, subset) — keep the run with the highest resolved_pct."""
    best = {}
    for r in runs:
        key = (r["suite"], r.get("subset", "full"))
        current = best.get(key)
        if current is None or (r.get("resolved_pct", 0) > current.get("resolved_pct", 0)):
            best[key] = r
    return best


def suite_label(suite, subset):
    name = {
        "swe-bench-lite": "SWE-bench Lite",
        "swe-bench-verified": "SWE-bench Verified",
        "swe-bench-full": "SWE-bench Full",
        "terminal-bench": "Terminal-bench",
        "humaneval": "HumanEval",
        "mbpp": "MBPP",
    }.get(suite, suite)
    if subset and subset != "full" and subset != "full-500":
        return f"{name} — {subset}"
    if subset == "full-500":
        return f"{name} (500)"
    return name


def runtime_label(r):
    if r.get("runtime") == "bundled":
        v = r.get("bahulam_version", "?")
        return f"@bahulam/code@{v}"
    return r.get("runtime", "?")


def format_pct(v):
    return f"{v:.1f} %" if v is not None else "—"


def render_table(runs):
    best = best_per_group(runs)
    rows = []
    for (suite, subset), r in sorted(best.items()):
        label = suite_label(suite, subset)
        pct = format_pct(r.get("resolved_pct"))
        resolved = r.get("resolved", "?")
        submitted = r.get("submitted", "?")
        link = f"[{r['run_id']}]({r['path']}/summary.md)"
        rows.append(
            f"| {label} | **{pct}** ({resolved}/{submitted}) | "
            f"`{r['model']}` | {runtime_label(r)} | {link} |"
        )
    header = (
        "| Suite | Best result | Model | Runtime | Run |\n"
        "|---|---|---|---|---|\n"
    )
    return header + "\n".join(rows)


def main():
    manifest = json.load(open(MANIFEST))
    table = render_table(manifest.get("runs", []))

    text = README.read_text()
    pattern = re.compile(
        re.escape(BEGIN_MARK) + r".*?" + re.escape(END_MARK),
        re.DOTALL,
    )
    new_block = f"{BEGIN_MARK}\n\n{table}\n\n{END_MARK}"
    if not pattern.search(text):
        raise SystemExit(
            f"marker pair {BEGIN_MARK!r} .. {END_MARK!r} not found in {README}"
        )
    new_text = pattern.sub(new_block, text)
    if new_text != text:
        README.write_text(new_text)
        print(f"README updated: {len(manifest['runs'])} runs summarized")
    else:
        print("README unchanged")


if __name__ == "__main__":
    main()
